changeSet.sql:
-- 1. Rename existing
ALTER TABLE trades RENAME TO trades_legacy;

-- 2. Create partitioned parent (same columns)
CREATE TABLE trades (
    id              BIGSERIAL,
    trade_ref       VARCHAR(30)   NOT NULL,
    instrument_id   BIGINT        NOT NULL,
    counterparty_id BIGINT        NOT NULL,
    asset_class     VARCHAR(20)   NOT NULL,
    side            VARCHAR(4)    NOT NULL,
    quantity        NUMERIC(18,4) NOT NULL,
    price           NUMERIC(18,4) NOT NULL,
    trade_date      DATE          NOT NULL,
    status          VARCHAR(20)   NOT NULL DEFAULT 'PENDING',
    deleted_at      TIMESTAMP,
    created_at      TIMESTAMP     NOT NULL DEFAULT now(),
    modified_at     TIMESTAMP,
    PRIMARY KEY (id, trade_date)
) PARTITION BY RANGE (trade_date);

-- 3. Recreate foreign keys and indexes on the parent table
ALTER TABLE trades ADD CONSTRAINT fk_trades_instrument
    FOREIGN KEY (instrument_id) REFERENCES instruments (id);
ALTER TABLE trades ADD CONSTRAINT fk_trades_counterparty
    FOREIGN KEY (counterparty_id) REFERENCES counterparties (id);

CREATE INDEX idx_trades_trade_date ON trades (trade_date);
CREATE INDEX idx_trades_status ON trades (status);

-- 4. Per-month partitions for April, May, June, July 2026
CREATE TABLE trades_y2026m04 PARTITION OF trades
    FOR VALUES FROM ('2026-04-01') TO ('2026-05-01');
CREATE TABLE trades_y2026m05 PARTITION OF trades
    FOR VALUES FROM ('2026-05-01') TO ('2026-06-01');
CREATE TABLE trades_y2026m06 PARTITION OF trades
    FOR VALUES FROM ('2026-06-01') TO ('2026-07-01');
CREATE TABLE trades_y2026m07 PARTITION OF trades
    FOR VALUES FROM ('2026-07-01') TO ('2026-08-01');

-- 5. Default partition for safety
CREATE TABLE trades_default PARTITION OF trades DEFAULT;

-- 6. Migrate data from legacy table
INSERT INTO trades (id, trade_ref, instrument_id, counterparty_id, asset_class, side, quantity, price, trade_date, status, deleted_at, created_at, modified_at)
SELECT id, trade_ref, instrument_id, counterparty_id, asset_class, side, quantity, price, trade_date, status, deleted_at, created_at, modified_at 
FROM trades_legacy;

-- 7. Drop legacy table
DROP TABLE trades_legacy;

rollback.sql:
ALTER TABLE trades RENAME TO trades_partitioned;

-- Create non-partitioned original
CREATE TABLE trades (
    id              BIGSERIAL PRIMARY KEY,
    trade_ref       VARCHAR(30)   NOT NULL UNIQUE,
    instrument_id   BIGINT        NOT NULL,
    counterparty_id BIGINT        NOT NULL,
    asset_class     VARCHAR(20)   NOT NULL,
    side            VARCHAR(4)    NOT NULL,
    quantity        NUMERIC(18,4) NOT NULL,
    price           NUMERIC(18,4) NOT NULL,
    trade_date      DATE          NOT NULL,
    status          VARCHAR(20)   NOT NULL DEFAULT 'PENDING',
    deleted_at      TIMESTAMP,
    created_at      TIMESTAMP     NOT NULL DEFAULT now(),
    modified_at     TIMESTAMP
);

-- Restore foreign keys and indexes
ALTER TABLE trades ADD CONSTRAINT fk_trades_instrument
    FOREIGN KEY (instrument_id) REFERENCES instruments (id);
ALTER TABLE trades ADD CONSTRAINT fk_trades_counterparty
    FOREIGN KEY (counterparty_id) REFERENCES counterparties (id);

CREATE INDEX idx_trades_trade_date ON trades (trade_date);
CREATE INDEX idx_trades_status ON trades (status);

-- Copy data back
INSERT INTO trades (id, trade_ref, instrument_id, counterparty_id, asset_class, side, quantity, price, trade_date, status, deleted_at, created_at, modified_at)
SELECT id, trade_ref, instrument_id, counterparty_id, asset_class, side, quantity, price, trade_date, status, deleted_at, created_at, modified_at 
FROM trades_partitioned;

-- Drop the partitioned parent (which cascades to drop child partitions)
DROP TABLE trades_partitioned CASCADE;
